-- Import 2025 physics exam questions with images and answer analysis.
USE smart_learning;
START TRANSACTION;
CREATE TEMPORARY TABLE tmp_physics_import_questions AS
SELECT id FROM question WHERE source = '2025高考课标卷物理';
CREATE TEMPORARY TABLE tmp_physics_import_exams AS
SELECT id FROM exam_paper WHERE name = '2025高考课标卷物理真题训练';
DELETE pa FROM practice_answer pa JOIN tmp_physics_import_questions q ON q.id = pa.question_id;
DELETE ar FROM answer_record ar JOIN tmp_physics_import_questions q ON q.id = ar.question_id;
DELETE mb FROM mistake_book mb JOIN tmp_physics_import_questions q ON q.id = mb.question_id;
DELETE eq FROM exam_question eq JOIN tmp_physics_import_questions q ON q.id = eq.question_id;
DELETE eq FROM exam_question eq JOIN tmp_physics_import_exams e ON e.id = eq.exam_id;
DELETE es FROM exam_submission es JOIN tmp_physics_import_exams e ON e.id = es.exam_id;
DELETE FROM exam_paper WHERE id IN (SELECT id FROM tmp_physics_import_exams);
DELETE FROM question WHERE id IN (SELECT id FROM tmp_physics_import_questions);
