INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_da1baf7adf AS CHAR), 'ESSAY', '【2025高考课标卷物理·第9题】<br>9. 某探究小组利用橡皮筋完成下面实验。<br>（1）将粘贴有坐标纸 木板竖直放置。橡皮筋的一端用图钉固定在木板上，另一端悬挂钩码。钩码质量分别为200g、250g、⋯、500g，平衡时橡皮筋底端在坐标纸上对应的位置如图（a）中圆点所示（钩码的质量在图中用数字标出）。悬挂的钩码质量分别为200g和300g时，橡皮筋底端位置间的距离为___________cm。<br>（2）根据图（a）中各点的位置可知，在所测范围内橡皮筋长度的增加量与所挂钩码的__________（选填“质量”或“质量的增加量”）成正比，由此可求出橡皮筋的劲度系数为___________ （公式见原题） （保留2位有效数字，重力加速度取 （公式见原题） ）。<br>（3）悬挂的钩码质量为 （公式见原题） 时，在橡皮筋底端施以水平向右的力 （公式见原题） ，平衡时橡皮筋方向如图（b）中虚线所示，图（b）中测力计的示数给出了力 （公式见原题） 的大小，则 （公式见原题） ___________ （公式见原题） ， （公式见原题） ___________g（选填“200”“300”或“400”）。<div class="question-images"><img src="/images/questions/2025/physics/img_006.png" alt="题目配图"></div>', NULL, '（1）1.90<br>（2） ①. 质量的增加量 ②. 52<br>（3） ①. 1.00 ②. 300', '参考答案：<br>（1）1.90<br>（2） ①. 质量的增加量 ②. 52<br>（3） ①. 1.00 ②. 300', 3, '2025高考课标卷物理', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
