INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_da1baf7adf AS CHAR), 'ESSAY', '【2025高考课标卷物理·第10题】<br>10. 用伏安法可以研究电学元件的伏安特性。阻值不随电流、电压变化的元件称为线性电阻元件，否则称为非线性电阻元件。<br>（1）利用伏安法测量某元件的电阻，电流表和电压表的示数分别记为 （公式见原题） 和 （公式见原题） 。若将电流表内接，则 （公式见原题） ___________元件两端的电压， （公式见原题） ___________元件的电阻；将电流表外接，则 （公式见原题） ___________流过元件的电流， （公式见原题） ___________元件的电阻。（均选填“小于”或“大于”）<br>（2）图（a）是某实验小组用电流表内接法测得的某元件的伏安特性曲线，由图可知，所测元件是__________（选填“线性”或“非线性”）电阻元件。随着电流的增加，元件的电阻__________（选填“增大”“不变”或“减小”）。<br>（3）利用电流表 （公式见原题） （内阻 （公式见原题） ）、电流表 （公式见原题） （内阻未知）以及一个用作保护电阻的定值电阻 （公式见原题） （阻值未知），测量电阻 （公式见原题） 的阻值。将图（b）中的器材符号的连线补充完整，完成实验电路原理图__________。按完整的实验电路测量 （公式见原题） ，某次测量中电流表 （公式见原题） 和 （公式见原题） 的示数分别为 （公式见原题） 和 （公式见原题） ，则 （公式见原题） ___________（用 （公式见原题） 和 （公式见原题） 表示）。<div class="question-images"><img src="/images/questions/2025/physics/img_007.png" alt="题目配图"><img src="/images/questions/2025/physics/img_009.png" alt="题目配图"><img src="/images/questions/2025/physics/img_010.png" alt="题目配图"></div>', NULL, '（1） ①. 大于 ②. 大于 ③. 大于 ④. 小于<br>（2） ①. 非线性 ②. 减小<br>（3） ①. ②. （公式见原题）', '参考答案：<br>（1） ①. 大于 ②. 大于 ③. 大于 ④. 小于<br>（2） ①. 非线性 ②. 减小<br>（3） ①. ②. （公式见原题）', 4, '2025高考课标卷物理', @admin_id, NOW());
SET @question_id := LAST_INSERT_ID();
