INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_c35cb6d924 AS CHAR), 'ESSAY', '【2025高考课标卷物理·第11题】<br>11. 电容器 形状变化会导致其电容变化，这一性质可用于设计键盘，简化原理图如图所示。键盘按键下的装置可视为平行板电容器，电容器的极板面积为 （公式见原题） 、间距为 （公式见原题） ，电容 （公式见原题） （ （公式见原题） 为常量）。按下键盘按键时，极板间的距离变为按压前的 （公式见原题） 倍；撤去按压，按键在弹力作用下复位。电容器充电后：<br>（1）若按压按键不改变电容器所带的电荷量，则按压后极板间的电压变为按压前的多少倍？<br>（2）若按压按键不改变电容器极板间的电压，则按压后极板间的电场强度大小变为按压前的多少倍？<div class="question-images"><img src="/images/questions/2025/physics/img_008.png" alt="题目配图"></div>', NULL, '（1） （公式见原题） 倍<br>（2） （公式见原题） 倍', '参考答案：<br>（1） （公式见原题） 倍<br>（2） （公式见原题） 倍', 4, '2025高考课标卷物理', @admin_id, NOW());
