INSERT INTO question (subject_id, knowledge_ids, type, content, options, answer, analysis, difficulty, source, created_by, created_at) VALUES (@subject_physics, CAST(@kp_15ccef12ae AS CHAR), 'ESSAY', '【2025高考课标卷物理·第12题】<br>12. 如图，物块P固定在水平面上，其上表面有半径为R的 （公式见原题） 圆弧轨道。P右端与薄板Q连在一起，圆弧轨道与Q上表面平滑连接。一轻弹簧的右端固定在Q上，另一端自由。质量为m的小球自圆弧顶端A点上方的B点自由下落，落到A点后沿圆弧轨道下滑，小球与弹簧接触后，当速度减小至刚接触时的 （公式见原题） 时弹簧的弹性势能为2mgR，此时断开P和Q的连接，从静止开始向右滑动。g为重力加速度大小，忽略空气阻力，圆弧轨道及Q的上、下表面均光滑，弹簧长度的变化始终在弹性限度内。<br>（1）求小球从落入圆弧轨道至离开圆弧轨道，重力对其做的功；<br>（2）求小球与弹簧刚接触时速度的大小及B、A两点间的距离；<br>（3）欲使P和Q断开后，弹簧的最大弹性势能等于2.2mgR，Q的质量应为多大？<br>（4）欲使P和Q断开后，Q的最终动能最大，Q的质量应为多大？', NULL, '（1） （公式见原题）<br>（2） （公式见原题） ， （公式见原题）<br>（3） （公式见原题）<br>（4） （公式见原题）', '参考答案：<br>（1） （公式见原题）<br>（2） （公式见原题） ， （公式见原题）<br>（3） （公式见原题）<br>（4） （公式见原题）', 4, '2025高考课标卷物理', @admin_id, NOW());
